update agenda_modelos_msg set texto = E'Olá, {nome}! 💛 Aqui é da DAS G.\n\nSua peça está pronta! A *entrega* está marcada para *{quando}*.{local}\n\nPara conferirmos tudo certinho, traga:\n✨ o sapato de salto que vai usar\n✨ as peças íntimas do dia (cinta e sutiã)\n\nAssim avaliamos o caimento e os detalhes exatamente como será no seu evento.\n\nTambém gostaríamos de *filmar este momento* para registrar o nosso trabalho, sempre com a sua autorização. Tudo bem pra você? 🎬\n\nConfirma sua presença com *SIM*? 💛', updated_at = now() where tipo = 'entrega';
